import toBlock from "./toBlock.ts";
import type * as t from "../index.ts";

/**
 * Ensure the `key` (defaults to "body") of a `node` is a block.
 * Casting it to a block if it is not.
 *
 * Returns the BlockStatement
 */
export default function ensureBlock(
  node: t.Node,
  key: string = "body",
): t.BlockStatement {
  // @ts-expect-error Fixme: key may not exist in node, consider remove key = "body"
  const result = toBlock(node[key], node);
  // @ts-expect-error Fixme: key may not exist in node, consider remove key = "body"
  node[key] = result;
  return result;
}

import {
  isBlockStatement,
  isFunction,
  isEmptyStatement,
  isStatement,
} from "../validators/generated/index.ts";
import {
  returnStatement,
  expressionStatement,
  blockStatement,
} from "../builders/generated/index.ts";
import type * as t from "../index.ts";

export default function toBlock(
  node: t.Statement | t.Expression,
  parent?: t.Node,
): t.BlockStatement {
  if (isBlockStatement(node)) {
    return node;
  }

  let blockNodes: t.Statement[] = [];

  if (isEmptyStatement(node)) {
    blockNodes = [];
  } else {
    if (!isStatement(node)) {
      if (isFunction(parent)) {
        node = returnStatement(node);
      } else {
        node = expressionStatement(node);
      }
    }

    blockNodes = [node];
  }

  return blockStatement(blockNodes);
}

import toIdentifier from "./toIdentifier.ts";

export default function toBindingIdentifierName(name: string): string {
  name = toIdentifier(name);
  if (name === "eval" || name === "arguments") name = "_" + name;

  return name;
}

import isValidIdentifier from "../validators/isValidIdentifier.ts";
import { isIdentifierChar } from "@babel/helper-validator-identifier";

export default function toIdentifier(input: string): string {
  input = input + "";

  // replace all non-valid identifiers with dashes
  let name = "";
  for (const c of input) {
    name += isIdentifierChar(c.codePointAt(0)) ? c : "-";
  }

  // remove all dashes and numbers from start of name
  name = name.replace(/^[-0-9]+/, "");

  // camel case
  name = name.replace(/[-\s]+(.)?/g, function (match, c) {
    return c ? c.toUpperCase() : "";
  });

  if (!isValidIdentifier(name)) {
    name = `_${name}`;
  }

  return name || "_";
}

import { isIdentifier } from "../validators/generated/index.ts";
import { stringLiteral } from "../builders/generated/index.ts";
